package com.hrflow.platform.department;
import com.hrflow.platform.common.ApiModels.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/departments") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('ADMIN','HR')") public class DepartmentController {private final DepartmentService service;
 @PostMapping @ResponseStatus(HttpStatus.CREATED)DepartmentView create(@Valid @RequestBody DepartmentInput i){return service.create(i);}@GetMapping Page<DepartmentView> list(@RequestParam(required=false)String search,@PageableDefault(sort="name")Pageable p){return service.list(search,p);}@GetMapping("/{id}")DepartmentView get(@PathVariable Long id){return service.get(id);}@PutMapping("/{id}")DepartmentView update(@PathVariable Long id,@Valid @RequestBody DepartmentInput i){return service.update(id,i);}@PatchMapping("/{id}/status")DepartmentView status(@PathVariable Long id,@Valid @RequestBody StatusUpdate i){return service.status(id,i);}}
